MAPA = {"titulo": "Nome do projeto", "ano": "Ano", "ano_fim": "Ano final", "cidade": "Cidade", "endereco_obra": "Endereço da obra",
        "identificacao_original": "Identificação original", "ambito_conteudo": "Observações"}
GRAVAR, COMPL = "--gravar" in sys.argv, "--complementos" in sys.argv
op = urllib.request.build_opener(urllib.request.HTTPCookieProcessor(http.cookiejar.CookieJar()))


def api(metodo, rota, corpo=None):
    req = urllib.request.Request(BASE + "/api" + rota, method=metodo, headers={"Content-Type": "application/json"},
                                 data=None if corpo is None else json.dumps(corpo).encode())
    try:
        with op.open(req, timeout=120) as r:
            return r.status, json.loads(r.read() or b"null")
    except urllib.error.HTTPError as e:
        try:
            return e.code, json.loads(e.read() or b"null")
        except ValueError:
            return e.code, None


def parar(msg):
    print("\nPAREI:", msg, "\nNada mais foi feito."); sys.exit(1)


print("== Cadastro de", TITULO, "(simulação: nada é gravado)" if not GRAVAR else "(GRAVANDO)")
email = input("E-mail de admin no painel: ").strip()
corpo = {"email": email, "senha": getpass.getpass("Senha (não aparece): ")}
st, r = api("POST", "/auth/login", corpo)
if st == 401 and "autenticador" in json.dumps(r, ensure_ascii=False):
    corpo["codigo_totp"] = input("Código do autenticador: ").strip(); st, r = api("POST", "/auth/login", corpo)
if st != 200:
    parar(f"login recusado ({st}): {r}")
st, fundos = api("GET", "/fundos/resumo")
if st != 200:
    parar(f"não consegui ler os fundos ({st})")
ja = [f for f in fundos if (f.get("titulo") or "").strip().lower() in ("renato viégas", "renato viegas")]
usadas = {(f.get("sigla") or "").upper() for f in fundos}
sigla = next((s for s in SIGLAS if s not in usadas), None)

# 1) fundo
ja_tem = 0
if ja:
    F, ja_tem = ja[0]["codigo"], int(ja[0].get("projetos") or 0)
    print(f"1) O fundo já existe: {F} {ja[0]['titulo']} (sigla {ja[0].get('sigla')}, {ja_tem} projetos). Não crio outro.")
else:
    if not sigla:
        parar(f"as siglas {SIGLAS} já são de outros fundos: escolha outra sigla de 3 letras.")
    st, v = api("POST", "/fundos/verificar", {"titulo": TITULO})
    par = (v or {}).get("parecidos") or []
    if par:
        parar("já existe fundo de nome parecido: " + "; ".join(f"{p.get('codigo')} {p.get('titulo')}" for p in par) + ". Confira no painel.")
    print(f"1) Fundo novo: '{TITULO}', sigla {sigla}, início 1967, pessoa (o código F0xx é o painel que dá).")
    if not GRAVAR:
        print("   (simulação: não criei)")
        F = None
    else:
        st, r = api("POST", "/fundos", {"titulo": TITULO, "sigla": sigla, "data_inicio": 1967, "tipo_agente": "pessoa"})
        if st != 200:
            parar(f"o painel recusou criar o fundo ({st}): {r}")
        F = r["codigo"]
        print(f"   criado: {F} · sigla {r['sigla']}" + (f" · site: {r['site'].get('erro')}" if (r.get("site") or {}).get("erro") else " · criado também no site"))

# 2) arquiteto
print("2) Arquiteto: nascimento 1943, São Paulo, 6 formas do nome, biografia com fonte.")
if GRAVAR:
    st, ags = api("GET", "/agentes?q=" + urllib.request.quote("Renato"))
    ag = [a for a in (ags or []) if (a.get("forma_autorizada") or "").lower() in ("renato viégas", "renato viegas") and F in (a.get("fundos") or "").split()]
    if not ag:
        parar("não achei o arquiteto ligado ao fundo novo: complete-o à mão (dados no guia).")
    st, r = api("PATCH", f"/agentes/{ag[0]['id']}", DADOS["arquiteto"])
    print("   " + ("completado" if st == 200 else f"o painel recusou ({st}): {r}"))
else:
    print("   (simulação: não alterei)")

# 3) projetos
for nome, linhas, vai in (("inventário", DADOS["inventario"], not ja_tem), ("complementos", DADOS["complementos"], COMPL)):
    motivo = "" if vai else (" (já importado: o fundo já tem projetos)" if nome == "inventário" else " (não importo: use --complementos depois de conferir)")
    print(f"3) Projetos — {nome}: {len(linhas)} linha(s)" + motivo)
    if not vai or not F:
        continue
    st, a = api("POST", "/planilha/analisar", {"fundo": F, "mapa": MAPA, "linhas": linhas, "nome_arquivo": f"renato_viegas_{nome}.xlsx"})
    if st != 200:
        parar(f"o painel recusou a análise ({st}): {a}")
    L = a.get("linhas") if isinstance(a, dict) else a
    prob = [(l["n"], l["problemas"]) for l in L if l["problemas"]]
    par = [(l["n"], [p["codigo"] for p in l["parecidos"]]) for l in L if l["parecidos"]]
    if prob or par:
        parar(f"a prévia tem problema {prob} ou projeto parecido já no fundo {par}: confira pela tela Importar planilha.")
    if GRAVAR:
        st, r = api("POST", "/planilha/criar", {"fundo": F, "mapa": MAPA, "linhas": linhas, "nome_arquivo": f"renato_viegas_{nome}.xlsx", "criar": [l["n"] for l in L]})
        if st != 200:
            parar(f"o painel recusou criar os projetos ({st}): {r}")
        cr = r.get("criados") or []
        print(f"   criados {len(cr)}: {cr[0]['codigo']} … {cr[-1]['codigo']}" if cr else "   nenhum criado")
print("\nPronto." if GRAVAR else "\nSimulação ok. Para gravar de verdade: python3 /tmp/cadastro_renato_viegas.py --gravar")
